    expect(res.filled).toBe(1);
    expect(loose.value.length).toBeGreaterThan(0);
  });
});

describe('clearAllForms', () => {
  it('resets filled values and states', () => {
    setDoc(`<form><input name="a" type="text"><input name="c" type="checkbox"></form>`);
