        async remove(keys) {
          for (const k of keys) delete store[k];
        },
      },
      local: {
        async get(keys) {
          const out: Record<string, unknown> = {};
          for (const k of keys) if (k in store) out[k] = store[k];
          return out;
        },
        async set(items) {
          for (const [k, v] of Object.entries(items)) store[k] = v;
        },
        async remove(keys) {
          for (const k of keys) delete store[k];
        },
      },
