    case 'company':
      return company(rng);
    case 'jobTitle':
      return jobTitle(rng);
    case 'url':
      return url({ rng });
    case 'sentence':
      return sentence('general', rng);
    case 'paragraph':
      return paragraph(3, 'general', rng);
    case 'number':
      return number(1, 9999, 1, rng);
    case 'date':
      return date(rng);
    case 'color':
      return color(rng);
    case 'password':
      return password({ rng });
